package com.pipican.client.boss;
import com.pipican.Pipican;import com.pipican.boss.LumynaraEntity;import net.minecraft.client.model.EntityModel;import net.minecraft.client.model.geom.ModelPart;import net.minecraft.client.renderer.entity.*;import net.minecraft.client.renderer.entity.state.LivingEntityRenderState;import net.minecraft.resources.Identifier;import net.minecraft.util.Mth;
/** Pulsing oracle bell, articulated tail, and reaching tentacle poses. */
public final class LumynaraRenderer extends MobRenderer<LumynaraEntity,LumynaraRenderer.State,LumynaraRenderer.Model>{public LumynaraRenderer(EntityRendererProvider.Context c){super(c,new Model(BossGeometry.load("lumynara_abyssal_oracle")),1.1f);}public static final class State extends LivingEntityRenderState{int phase,action;float remaining,hurt;}@Override public State createRenderState(){return new State();}@Override public Identifier getTextureLocation(State s){return Pipican.id("textures/entity/boss/lumynara_"+(s.phase==2?"oracle":"abyssal")+".png");}@Override public void extractRenderState(LumynaraEntity e,State s,float p){super.extractRenderState(e,s,p);s.phase=e.phase();s.action=e.lumynaraAction();s.remaining=Math.max(0,e.abilityTicksRemaining()-p);s.hurt=e.hurtTime-p;}@Override protected net.minecraft.world.phys.AABB getBoundingBoxForCulling(LumynaraEntity e){return super.getBoundingBoxForCulling(e).inflate(2.1);}
 static final class Model extends EntityModel<State>{private final ModelPart body,head,bell;private final ModelPart[] tails=new ModelPart[4],tentacles=new ModelPart[8];Model(ModelPart r){super(r);body=r.getChild("root").getChild("body");head=body.getChild("head");tails[0]=body.getChild("tail_0");for(int i=1;i<4;i++)tails[i]=tails[i-1].getChild("tail_"+i);bell=body.getChild("bell");for(int i=0;i<8;i++)tentacles[i]=bell.getChild("tentacle_"+i);}@Override public void setupAnim(State s){super.setupAnim(s);float sway=Mth.sin(s.ageInTicks*.16f),gait=Mth.clamp(s.walkAnimationSpeed,0,1),tell=1-Mth.clamp(s.remaining/60f,0,1);head.yRot=Mth.clamp(s.yRot,-30,30)*Mth.DEG_TO_RAD;head.xRot=Mth.clamp(s.xRot,-12,12)*Mth.DEG_TO_RAD;for(int i=0;i<4;i++){tails[i].yRot=sway*(.1f+i*.045f);tails[i].xRot=.025f*Mth.cos(s.ageInTicks*.12f-i*.3f);}bell.xRot=.03f*Mth.sin(s.ageInTicks*.11f);bell.yRot=sway*.025f;for(int i=0;i<8;i++){tentacles[i].xRot=.08f*Mth.sin(s.ageInTicks*.13f+i*.9f);tentacles[i].zRot=.08f*Mth.cos(s.ageInTicks*.13f+i*.9f);}
 switch(s.action){case 1->{head.xRot-=.12f*tell;}case 2->{head.xRot=-.18f*tell;bell.xRot=-.14f*tell;}case 3->{bell.xRot=-.1f*tell;for(int i=0;i<8;i++)tentacles[i].xRot+=.08f*tell;}case 4->{bell.xRot=.2f*tell;for(int i=0;i<8;i++)tentacles[i].zRot+=.16f*tell;}case 5->{bell.xRot=-.2f;for(int i=0;i<8;i++)tentacles[i].zRot=(i%2==0?-.18f:.18f);}case 6->{bell.xRot=-.12f;for(int i=0;i<8;i++)tentacles[i].xRot-=.08f;}default->{}}if(s.phase==2)for(int i=0;i<4;i++)tails[i].yRot+=sway*.025f*(i+1);if(s.hurt>0)body.zRot=.035f*Mth.sin(s.hurt*1.4f);if(s.deathTime>0)body.xRot=.55f;}}
}
